function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function parseList(value, label) {
  const parsed = typeof value === 'string' ? JSON.parse(value || '[]') : value;
  if (!Array.isArray(parsed)) throw new Error(label + ' must be a JSON array.');
  return parsed;
}

function publicUrl(value, label, required = false) {
  if (!value) { if (required) throw new Error(label + ' is required for production.'); return ''; }
  const text=String(value).trim(), match=/^https:\/\/([^/?#]+)([^\s]*)$/i.exec(text);
  if (!match || /[@\\\s]/.test(match[1]) || /[\x00-\x20<>"']/.test(text)) throw new Error(label + ' must be an HTTPS URL without embedded credentials.');
  const host=match[1].replace(/:\d+$/,'').toLowerCase();
  if (!/^[a-z0-9.-]+$/.test(host) || !host.includes('.') || /^(localhost|127\.|0\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)/i.test(host)) throw new Error(label + ' must be a public product or asset link.');
  return 'https://'+match[1].toLowerCase()+(match[2]||'/');
}

function validateInput(input, method) {
  const errors = [], warnings = [];
  let products = [], references = [];
  const production = input['Run mode'] === 'Generate and return files';
  const campaign = String(input['Campaign name'] || method.title).trim().slice(0,120);
  const variantCount = Number(input['Variant count'] ?? (method.enhanced ? 3 : 1));
  const maxVariants = Number(input.maxVariants ?? 3);
  if (!Number.isInteger(variantCount) || variantCount < 1 || variantCount > maxVariants || maxVariants > 10) errors.push('Variant count must be 1–' + Math.min(maxVariants,10) + '.');
  try {
    products = parseList(input['Product details JSON'], 'Product details');
    if (products.length !== (method.kind === 'roundup' ? 3 : 1)) throw new Error(method.kind === 'roundup' ? 'Supply exactly three products.' : 'Supply exactly one product.');
    products = products.map((p,i) => {
      if (!p || typeof p !== 'object' || !String(p.name || '').trim()) throw new Error('Product ' + (i+1) + ' needs a name.');
      const facts = Array.isArray(p.facts) ? p.facts : [];
      if (production && (!facts.length || facts.some(f => !f.text || !f.evidenceUrl))) throw new Error(p.name + ': add verified facts with evidenceUrl before production.');
      const assets = (Array.isArray(p.assetUrls) ? p.assetUrls : []).map(u => publicUrl(u, p.name + ' asset'));
      const assetFiles=(p.assetFiles||[]).filter(f=>(input.uploadedAssetNames||[]).includes(f));
      if (production && ((!assets.length&&!assetFiles.length) || p.rightsConfirmed !== true)) throw new Error(p.name + ': attach authentic product assets (URLs or matching uploaded assetFiles) and confirm rights.');
      const productUrl = publicUrl(p.productUrl,p.name + ' product URL',production);
      const destinationUrl = publicUrl(p.destinationUrl || p.productUrl,p.name + ' destination URL',production);
      if (production && !p.offerCheckedAt) throw new Error(p.name + ': add offerCheckedAt (YYYY-MM-DD) after checking availability and destination.');
      if (p.offerCheckedAt && (!/^\d{4}-\d{2}-\d{2}$/.test(p.offerCheckedAt) || !Number.isFinite(Date.parse(p.offerCheckedAt)))) throw new Error(p.name + ': invalid offerCheckedAt date.');
      return {name:String(p.name).trim(),productUrl,destinationUrl,assetUrls:assets,assetFiles,rightsConfirmed:p.rightsConfirmed===true,
        facts:facts.map(f=>({text:String(f.text || '').slice(0,350),evidenceUrl:publicUrl(f.evidenceUrl,'Fact evidence',production)})),
        offerCheckedAt:p.offerCheckedAt || '',affiliate:p.affiliate===true,commissionPercent:p.commissionPercent ?? null,
        priceText:p.priceText ? String(p.priceText) : '',verifiedSales:p.verifiedSales ?? null,metricDate:p.metricDate || '',
        metricEvidenceUrl:publicUrl(p.metricEvidenceUrl,'Metric evidence'),audience:String(p.audience || method.audience),
        contentAngle:String(p.contentAngle || ['Feature close-up','Everyday use context','Who should compare it'][i]),caution:String(p.caution || '')};
    });
  } catch (e) { errors.push(e.message); }
  try {
    references = parseList(input['Reference reels JSON'] || '[]','Reference reels').map(r=>({
      url:publicUrl(r.url,'Reference URL',true),creator:String(r.creator || ''),views:Number(r.views || 0),
      hookPattern:String(r.hookPattern || ''),originalAngle:String(r.originalAngle || ''),topic:String(r.topic||''),pacing:String(r.pacing||''),visualPattern:String(r.visualPattern||''),ctaPattern:String(r.ctaPattern||''),checkedAt:String(r.checkedAt || '')
    }));
    if (references.some(r=>!Number.isFinite(r.views)||r.views<0)) throw new Error('Reference view counts must be nonnegative numbers.');
  } catch (e) { errors.push(e.message); }
  if (method.kind === 'organic' && production && !references.length) errors.push('Add at least one reference reel and an original angle for the organic method.');
  if (method.kind === 'organic' && references.some(r=>!r.originalAngle)) warnings.push('Some references need your original angle before filming.');
  if (!production) warnings.push('Planning mode: incomplete facts and links remain marked. This package is not publish-ready.');
  if (method.kind === 'roundup') warnings.push('Three selected products is a user-requested adaptation, not a verified market-wide top-three ranking.');
  const requestedProvider = input['Provider preference'] || 'Supercool';
  const provider = method.enhanced ? (requestedProvider === 'Higgsfield' ? 'Higgsfield' : 'Supercool') : method.sourceProvider;
  return {valid:errors.length===0,errors,warnings,products,references,campaign,production,variantCount,provider,
    maxUploadMB:Number(input.maxUploadMB || 100),maxAttempts:Number(input.maxGenerationAttempts||3),method,cta:String(input['Primary CTA'] || method.cta),
    avatarDescription:String(input['Avatar description']||'Consistent generated adult, age 25+, natural expressions and conversational delivery.'),
    prohibitedClaims:String(input['Prohibited claims']||'guaranteed results;best-selling;I wore;I tested;I used;I bought').split(';').map(s=>s.trim()).filter(Boolean),
    executionId:String(input.executionId || 'preview'),publishStatus:'NOT_PUBLISHED',paidSpend:0};
}

function chooseReferences(ctx) {
  const seen = new Set();
  const unique = ctx.references.filter(r=>{const key=r.url.split(/[?#]/)[0];if(seen.has(key))return false;seen.add(key);return true;});
  const sorted = unique.sort((a,b)=>b.views-a.views);
  const qualified = sorted.filter(r=>r.views>10000000);
  return {...ctx,selectedReferences:(ctx.method.kind==='organic'&&!ctx.method.enhanced?qualified:sorted).slice(0,10),
    referenceNote:ctx.method.kind==='organic'?'Source recommends 10 relevant pages, videos over 10 million views and 10 original recordings/day. Imported view counts are user-supplied, not live-verified.':''};
}

function createCreativePack(ctx) {
  const {method,products} = ctx;
  const first = products[0] || {name:'[PRODUCT]',facts:[],assetUrls:[]};
  const name = first.name;
  const facts = first.facts.map(f=>f.text);
  const verifiedLine = facts[0] || '[ADD A VERIFIED PRODUCT FEATURE]';
  const secondary = facts[1] || 'Check the product page for the current specifications.';
  const prompts = [];
  let hooks = method.kind==='fashion' ? [
    'Before choosing your next pair of jeans, look at the details.',
    'Three angles. One pair of jeans. Here is what to check.',
    'Build an outfit around the jeans, then check the fit guide.'
  ] : method.kind==='pet' ? [
    'A closer look at the next addition to your pet-care kit.',
    'Before adding this to your pet-care routine, check these details.',
    'One product, up close: see what comes with it.'
  ] : method.kind==='roundup' ? [
    'Three product finds to compare before you buy.',
    'Which of these three belongs on your shortlist?',
    'Three different picks. Here is the detail that matters for each.'
  ] : [
    'One small detail to check before you choose '+name+'.',
    'Here is a closer look at '+name+'.',
    'Thinking about '+name+'? Start with the details.'
  ];
  if(method.kind==='organic' && ctx.selectedReferences.some(r=>r.originalAngle)) hooks=ctx.selectedReferences.filter(r=>r.originalAngle).map(r=>r.originalAngle);
  const disclosure = products.some(p=>p.affiliate) ? 'Affiliate links — I may earn a commission.' : 'Product promotion for '+name+'.';
  const duration = method.kind==='pet'&&method.enhanced?15:30;
  const frames = method.kind==='fashion' ? [
    'Consenting or generated adult, age 25+, neutral full-length outfit view. Preserve the exact jeans design; label AI-generated scenes.',
    'Product-only detail of waistband, seams and closure, matching supplied photography. No invented stretch, sizing or shaping proof.',
    'Front and side outfit views, no body reshaping or before/after comparisons. An AI try-on is illustrative, not fit evidence.',
    'Authentic product photo, product name, sizing/availability CTA.'
  ] : method.kind==='pet' ? [
    'Authentic product close-up on a clean surface.',
    'Hands show the physical controls or included parts using supplied footage; do not invent animal contact or safe-use demonstrations.',
    'Product detail matched to the verified feature.',
    'Product and LumiPaw name with a clear store CTA.'
  ] : method.kind==='roundup' ? ['Three authentic product photos in a clean opening.','Product 1: one verified detail.','Product 2: one verified detail.','Product 3: one verified detail and comparison CTA.'] : [
    'Original recording inspired only by the reference hook structure, without copying its footage or script.',
    'Show the real product and the supplied verified detail.',
    'Show a second detail or practical context without fabricated results.',
    'Product photo and one direct offer CTA.'
  ];
  for(let i=0;i<ctx.variantCount;i++) {
    const id='V'+String(i+1).padStart(2,'0');
    const times=duration===15?[[0,3],[3,8],[8,12],[12,15]]:method.kind==='roundup'?[[0,3],[3,11],[11,19],[19,27],[27,30]]:[[0,3],[3,10],[10,20],[20,26],[26,30]];
    let lines=duration===15?[hooks[i%hooks.length],name+'. '+verifiedLine,secondary,ctx.cta]:[hooks[i%hooks.length],'Take a closer look at '+name+'.',verifiedLine,secondary,ctx.cta];
    if(method.kind==='roundup') lines=[hooks[i%hooks.length],...products.map((p,j)=>`${j+1}. ${p.name}. ${p.facts[0]?.text || '[ADD VERIFIED DETAIL]'}.`),ctx.cta];
    const scenes=times.map(([start,end],j)=>({start,end,visual:frames[Math.min(j,frames.length-1)],voiceover:lines[j],overlay:j===0?disclosure:lines[j],
      camera:['Medium eye-level, slight push-in','Stable product close-up','Slow side-to-side product view','Gentle return to medium framing','Locked product end card'][j],
      gesture:['Hold product visibly or indicate garment','Point once to the named detail','Demonstrate only the supplied authentic action','Open hand toward the product','Small invitation toward the CTA'][j],
      expression:['Curious, relaxed','Attentive','Matter-of-fact','Warm, subtle smile','Friendly, no exaggerated surprise'][j]}));
    const sourceSteps=method.sourceSteps.map((s,j)=>`${j+1}. ${s}`).join('\n');
    const providerSteps=ctx.provider==='Supercool' ? 'Open Supercool → Studio → Marketing Studio. Pick/reuse an adult influencer (or product-only POV), add authentic product photos/URL, select camera persona and opening psychology, paste this brief. Preview the credit quote; start with ONE variation. Review script and shot plan, Generate, then download the result. Return the MP4 to the n8n upload page.' : ctx.provider==='Higgsfield' ? 'Open your authenticated Higgsfield production surface. Select an available product/UGC or try-on workflow and verify its current model and credit quote. Use the supplied photos and timed brief; generate one test and download the MP4. Return it to n8n. No n8n MCP access or API endpoint is assumed.' : method.sourceHandoff;
    const prompt=`ROLE\nYou are a UGC commercial director and editor creating a finished original ${duration}-second vertical video.\n\nCONTEXT\nCampaign: ${ctx.campaign}\nAudience: ${first.audience || method.audience}\nProducts and factual evidence:\n${JSON.stringify(products,null,2)}\n\nOBJECTIVE\nProduce ${id}: ${hooks[i%hooks.length]}\n${ctx.production?'Production brief':'PLANNING DRAFT — replace bracketed missing facts before generating.'}\n\nSOURCE METHOD\n${sourceSteps}\nSource: ${method.sourceUrl}\n${method.adaptation}\n\nTIMED SCRIPT AND SHOTS\n${scenes.map(s=>`${s.start.toFixed(0).padStart(2,'0')}–${s.end.toFixed(0).padStart(2,'0')}s | Visual: ${s.visual}\nVoice: ${s.voiceover}\nText: ${s.overlay}`).join('\n\n')}\n\nDIRECTION\nNatural spoken delivery, concrete gestures, one action per shot, no robotic sales pitch. Use the same adult creator and garment/product across shots. Keep captions in safe margins. Preserve exact physical product design. For fashion use GRWM Try-On; for product-only pet content use POV Demo. ${ctx.method.enhanced?'Test this hook before making additional variations; keep the body and CTA constant for a clean hook comparison.':''}\n\nCONSTRAINTS\nUse only supplied facts. No fabricated reviews, personal-use testimonials, rankings, discounts, health/safety claims, sales or performance results. Never present an AI try-on as proof of fit or product performance. Show affiliate/brand disclosure visibly and in the caption. Label synthetic creator/scene content as AI-generated. Licensed audio only. ${method.kind==='roundup'?'Say three selected finds; do not claim top-selling unless dated comparative data actually establishes that ranking.':''}\n\nOUTPUT\nReturn the actual MP4, final voiceover transcript, captions/SRT if timing is available, provider/model and credits used, and any unresolved factual issue. Target 1080×1920, 9:16, intelligible voice and legible text. Do not publish or buy ads.\n\nPROVIDER HANDOFF\n${providerSteps}`;
    const destination=first.destinationUrl || '[ADD PRODUCT OR AFFILIATE LINK]';
    const detailedPrompt=prompt.replace('SOURCE METHOD',method.enhanced?'SOURCE REFERENCE ONLY — superseded by the provider handoff below':'SOURCE METHOD')+'\n\nAVATAR BRIEF\n'+ctx.avatarDescription+'\n\nPERFORMANCE DETAILS\n'+scenes.map(s=>`${s.start}–${s.end}s: Camera: ${s.camera}. Gesture: ${s.gesture}. Expression: ${s.expression}.`).join('\n')+'\n\nREFERENCE PATTERNS\n'+JSON.stringify(ctx.selectedReferences)+'\n\nPRODUCT ANGLES\n'+products.map(p=>p.name+': '+p.contentAngle).join('\n')+'\n\nPROHIBITED COPY\n'+ctx.prohibitedClaims.join('; ');
    const offerCaption=method.kind==='roundup'?products.map((p,j)=>`${j+1}. ${p.name}: ${p.destinationUrl||'[ADD LINK]'}`).join(' | '):name+'. '+destination;
    prompts.push({id,hook:hooks[i%hooks.length],duration,scenes,prompt:detailedPrompt,caption:disclosure+' '+offerCaption+' '+ctx.cta+(ctx.provider==='Original camera footage'?'':' #AIGenerated'),destinationUrl:destination,status:'BRIEF_READY'});
  }
  const rankedProducts=products.map((p,index)=>({position:index+1,name:p.name,basis:'User-supplied order; not a sales ranking',verifiedSales:p.verifiedSales,metricDate:p.metricDate,metricEvidenceUrl:p.metricEvidenceUrl}));
  const status=ctx.production?'AWAITING_'+ctx.provider.toUpperCase().replace(/[^A-Z0-9]+/g,'_')+'_RENDER':'BRIEF_READY';
  const html='<h2>'+escapeHtml(ctx.campaign)+'</h2><p><strong>Job ID: '+escapeHtml(ctx.executionId)+'</strong> · '+escapeHtml(status)+'</p><p>'+escapeHtml(method.adaptation)+'</p><p>Provider: '+escapeHtml(ctx.provider)+'. Start with one test. No automatic credits or ad spend.</p>'+ctx.warnings.map(w=>'<p>'+escapeHtml(w)+'</p>').join('')+prompts.map(p=>'<h3>'+p.id+' — '+escapeHtml(p.hook)+'</h3><pre>'+escapeHtml(p.prompt)+'</pre><p><strong>Caption:</strong> '+escapeHtml(p.caption)+'</p>').join('');
  return {...ctx,rankedProducts,variants:prompts,status,productionHtml:html,productionInstructions:prompts[0]?.prompt || ''};
}

function reviewReceipt(pack,form,files) {
  const planOnly=form['Return type']==='Brief only';
  const errors=[];
  const ids=String(form['Returned variant IDs'] || '').split(',').map(x=>x.trim()).filter(Boolean);
  if(!planOnly) {
    if(String(form['Job ID']||'')!==String(pack.executionId)) errors.push('Job ID does not match this waiting execution.');
    if(!pack.production) errors.push('Start a Production run with complete product evidence before accepting rendered assets.');
    if(!files.length) errors.push('Upload at least one MP4/MOV file.');
    if(files.length!==ids.length) errors.push('Provide one variant ID for each uploaded file, in the same order.');
    if(new Set(ids).size!==ids.length || ids.some(id=>!pack.variants.some(v=>v.id===id))) errors.push('Returned variant IDs must be unique IDs shown in the brief.');
    if(form['Review result']!=='Checked product, text, sound and disclosures') errors.push('Complete the product, captions, audio and disclosure review.');
    for(const f of files) {
      if(!/\.(mp4|mov)$/i.test(f.name) || !f.validContainer) errors.push('Invalid video container: '+f.name);
      if(f.bytes>pack.maxUploadMB*1024*1024) errors.push('Video exceeds upload limit: '+f.name);
      if(!f.width||!f.height||f.width>=f.height) errors.push('Video must contain a vertical video track: '+f.name);
      const target=pack.variants.find(v=>v.id===ids[files.indexOf(f)])?.duration||30;
      if(!Number.isFinite(f.duration)||Math.abs(f.duration-target)>Math.max(3,target*0.2)) errors.push('Video duration is outside the target tolerance: '+f.name);
    }
    if(new Set(files.map(f=>f.sha256)).size!==files.length) errors.push('Duplicate renders detected by SHA-256.');
    const attempts=Number(form['Generation attempts']);
    if(!Number.isInteger(attempts)||attempts<1||attempts>pack.maxAttempts) errors.push('Generation attempts must be 1–'+pack.maxAttempts+'.');
    const finalText=String(form['Final transcript']||'');
    if(!finalText.trim()) errors.push('Paste the final transcript for copy checks.');
    for(const term of pack.prohibitedClaims) if(finalText.toLowerCase().includes(term.toLowerCase())) errors.push('Review prohibited wording in transcript: '+term);
    if(!Number.isFinite(Number(form['Credits used'])) || Number(form['Credits used'])<0) errors.push('Credits used must be a nonnegative number.');
  }
  return {valid:errors.length===0,errors,planOnly,ids,status:planOnly?'BRIEF_ONLY':'ASSETS_RETURNED_NOT_PUBLISHED',
    review:planOnly?'Not performed':form['Review result'],providerUsed:form['Provider used'] || pack.provider,creditsUsed:planOnly?0:Number(form['Credits used']),
    attempts:Number(form['Generation attempts']||0),actualTranscript:String(form['Final transcript'] || ''),renderedFiles:files.map((f,i)=>({...f,variantId:ids[i] || null})),
    automaticChecks:'MP4/MOV container structure, video-track dimensions, duration tolerance, size, SHA-256 duplicate detection, job and variant mapping, and configured prohibited phrases. Decoding, product/character identity, all factual claims, caption timing and audio quality require the recorded operator review.'};
}

function sha256Bytes(bytes) {
  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const n=bytes.length,total=Math.ceil((n+9)/64)*64,w=new Array(64),rotr=(x,n)=>(x>>>n)|(x<<(32-n));
  const byteAt=p=>p<n?bytes[p]:p===n?128:p>=total-8?Math.floor(n*8/Math.pow(256,total-1-p))&255:0;
  for(let off=0;off<total;off+=64){
    for(let i=0;i<16;i++){const p=off+i*4;w[i]=((byteAt(p)<<24)|(byteAt(p+1)<<16)|(byteAt(p+2)<<8)|byteAt(p+3))>>>0;}
    for(let i=16;i<64;i++){const a=w[i-15],b=w[i-2];w[i]=((rotr(a,7)^rotr(a,18)^(a>>>3))+w[i-16]+(rotr(b,17)^rotr(b,19)^(b>>>10))+w[i-7])>>>0;}
    let [a,b,c,d,e,f,g,h]=H;
    for(let i=0;i<64;i++){const t1=(h+(rotr(e,6)^rotr(e,11)^rotr(e,25))+((e&f)^((~e)&g))+K[i]+w[i])>>>0,t2=((rotr(a,2)^rotr(a,13)^rotr(a,22))+((a&b)^(a&c)^(b&c)))>>>0;h=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;}
    H=H.map((v,i)=>(v+[a,b,c,d,e,f,g,h][i])>>>0);
  }
  return H.map(x=>x.toString(16).padStart(8,'0')).join('');
}

function inspectMp4(buf) {
  const boxes=(start,end)=>{const out=[];for(let p=start;p<end;){if(p+8>end)throw new Error('Truncated atom');let size=buf.readUInt32BE(p),header=8;const type=buf.subarray(p+4,p+8).toString();if(size===1){if(p+16>end)throw new Error('Truncated large atom');size=Number(buf.readBigUInt64BE(p+8));header=16;}if(size===0)size=end-p;if(size<header||p+size>end||!Number.isSafeInteger(size))throw new Error('Invalid atom size');out.push({type,start:p+header,end:p+size});p+=size;}return out;};
  const durationOf=b=>{const p=b.start,version=buf[p],o=version===1?20:12;if(p+o+(version===1?12:8)>b.end)throw new Error('Truncated media header');const scale=buf.readUInt32BE(p+o),ticks=version===1?Number(buf.readBigUInt64BE(p+o+4)):buf.readUInt32BE(p+o+4);return scale?ticks/scale:NaN;};
  try{
    const top=boxes(0,buf.length),moov=top.find(b=>b.type==='moov');
    if(!top.some(b=>b.type==='ftyp')||!top.some(b=>b.type==='mdat')||!moov)throw new Error('Missing movie atoms');
    const movie=boxes(moov.start,moov.end);
    for(const track of movie.filter(b=>b.type==='trak')){
      const children=boxes(track.start,track.end),tkhd=children.find(b=>b.type==='tkhd'),mdia=children.find(b=>b.type==='mdia');if(!tkhd||!mdia)continue;
      const media=boxes(mdia.start,mdia.end),hdlr=media.find(b=>b.type==='hdlr'),mdhd=media.find(b=>b.type==='mdhd');
      if(!hdlr||buf.subarray(hdlr.start+8,hdlr.start+12).toString()!=='vide'||!mdhd)continue;
      let width=buf.readUInt32BE(tkhd.end-8)/65536,height=buf.readUInt32BE(tkhd.end-4)/65536;
      const matrix=tkhd.start+(buf[tkhd.start]===1?52:40);
      if(Math.abs(buf.readInt32BE(matrix))<2 && Math.abs(buf.readInt32BE(matrix+4))===65536)[width,height]=[height,width];
      return {validContainer:width>0&&height>0,duration:durationOf(mdhd),width,height};
    }
    throw new Error('No video track');
  }catch(e){return {validContainer:false,width:0,height:0,duration:0,containerError:e.message};}
}
const input={...$input.first().json,executionId:$execution.id,uploadedAssetNames:Object.values($("Start · edit product details").first().binary||{}).map(b=>b.fileName)};
