function parseList(value, label) {
  const parsed = typeof value === 'string' ? JSON.parse(value || '[]') : value;
  if (!Array.isArray(parsed)) throw new Error(label + ' must be a JSON array.');
  return parsed;
}

function publicUrl(value, label, required = false) {
  if (!value) { if (required) throw new Error(label + ' is required for production.'); return ''; }
  const text=String(value).trim(), match=/^https:\/\/([^/?#]+)([^\s]*)$/i.exec(text);
  if (!match || /[@\\\s]/.test(match[1]) || /[\x00-\x20<>"']/.test(text)) throw new Error(label + ' must be an HTTPS URL without embedded credentials.');
  const host=match[1].replace(/:\d+$/,'').toLowerCase();
  if (!/^[a-z0-9.-]+$/.test(host) || !host.includes('.') || /^(localhost|127\.|0\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)/i.test(host)) throw new Error(label + ' must be a public product or asset link.');
  return 'https://'+match[1].toLowerCase()+(match[2]||'/');
}

function validateInput(input, method) {
  const errors = [], warnings = [];
  let products = [], references = [];
  const production = input['Run mode'] === 'Generate and return files';
  const campaign = String(input['Campaign name'] || method.title).trim().slice(0,120);
  const variantCount = Number(input['Variant count'] ?? (method.enhanced ? 3 : 1));
  const maxVariants = Number(input.maxVariants ?? 3);
  if (!Number.isInteger(variantCount) || variantCount < 1 || variantCount > maxVariants || maxVariants > 10) errors.push('Variant count must be 1–' + Math.min(maxVariants,10) + '.');
  try {
    products = parseList(input['Product details JSON'], 'Product details');
    if (products.length !== (method.kind === 'roundup' ? 3 : 1)) throw new Error(method.kind === 'roundup' ? 'Supply exactly three products.' : 'Supply exactly one product.');
    products = products.map((p,i) => {
      if (!p || typeof p !== 'object' || !String(p.name || '').trim()) throw new Error('Product ' + (i+1) + ' needs a name.');
      const facts = Array.isArray(p.facts) ? p.facts : [];
      if (production && (!facts.length || facts.some(f => !f.text || !f.evidenceUrl))) throw new Error(p.name + ': add verified facts with evidenceUrl before production.');
      const assets = (Array.isArray(p.assetUrls) ? p.assetUrls : []).map(u => publicUrl(u, p.name + ' asset'));
      const assetFiles=(p.assetFiles||[]).filter(f=>(input.uploadedAssetNames||[]).includes(f));
      if (production && ((!assets.length&&!assetFiles.length) || p.rightsConfirmed !== true)) throw new Error(p.name + ': attach authentic product assets (URLs or matching uploaded assetFiles) and confirm rights.');
      const productUrl = publicUrl(p.productUrl,p.name + ' product URL',production);
      const destinationUrl = publicUrl(p.destinationUrl || p.productUrl,p.name + ' destination URL',production);
      if (production && !p.offerCheckedAt) throw new Error(p.name + ': add offerCheckedAt (YYYY-MM-DD) after checking availability and destination.');
      if (p.offerCheckedAt && (!/^\d{4}-\d{2}-\d{2}$/.test(p.offerCheckedAt) || !Number.isFinite(Date.parse(p.offerCheckedAt)))) throw new Error(p.name + ': invalid offerCheckedAt date.');
      return {name:String(p.name).trim(),productUrl,destinationUrl,assetUrls:assets,assetFiles,rightsConfirmed:p.rightsConfirmed===true,
        facts:facts.map(f=>({text:String(f.text || '').slice(0,350),evidenceUrl:publicUrl(f.evidenceUrl,'Fact evidence',production)})),
        offerCheckedAt:p.offerCheckedAt || '',affiliate:p.affiliate===true,commissionPercent:p.commissionPercent ?? null,
        priceText:p.priceText ? String(p.priceText) : '',verifiedSales:p.verifiedSales ?? null,metricDate:p.metricDate || '',
        metricEvidenceUrl:publicUrl(p.metricEvidenceUrl,'Metric evidence'),audience:String(p.audience || method.audience),
        contentAngle:String(p.contentAngle || ['Feature close-up','Everyday use context','Who should compare it'][i]),caution:String(p.caution || '')};
    });
  } catch (e) { errors.push(e.message); }
  try {
    references = parseList(input['Reference reels JSON'] || '[]','Reference reels').map(r=>({
      url:publicUrl(r.url,'Reference URL',true),creator:String(r.creator || ''),views:Number(r.views || 0),
      hookPattern:String(r.hookPattern || ''),originalAngle:String(r.originalAngle || ''),topic:String(r.topic||''),pacing:String(r.pacing||''),visualPattern:String(r.visualPattern||''),ctaPattern:String(r.ctaPattern||''),checkedAt:String(r.checkedAt || '')
    }));
    if (references.some(r=>!Number.isFinite(r.views)||r.views<0)) throw new Error('Reference view counts must be nonnegative numbers.');
  } catch (e) { errors.push(e.message); }
  if (method.kind === 'organic' && production && !references.length) errors.push('Add at least one reference reel and an original angle for the organic method.');
  if (method.kind === 'organic' && references.some(r=>!r.originalAngle)) warnings.push('Some references need your original angle before filming.');
  if (!production) warnings.push('Planning mode: incomplete facts and links remain marked. This package is not publish-ready.');
  if (method.kind === 'roundup') warnings.push('Three selected products is a user-requested adaptation, not a verified market-wide top-three ranking.');
  const requestedProvider = input['Provider preference'] || 'Supercool';
  const provider = method.enhanced ? (requestedProvider === 'Higgsfield' ? 'Higgsfield' : 'Supercool') : method.sourceProvider;
  return {valid:errors.length===0,errors,warnings,products,references,campaign,production,variantCount,provider,
    maxUploadMB:Number(input.maxUploadMB || 100),maxAttempts:Number(input.maxGenerationAttempts||3),method,cta:String(input['Primary CTA'] || method.cta),
    avatarDescription:String(input['Avatar description']||'Consistent generated adult, age 25+, natural expressions and conversational delivery.'),
    prohibitedClaims:String(input['Prohibited claims']||'guaranteed results;best-selling;I wore;I tested;I used;I bought').split(';').map(s=>s.trim()).filter(Boolean),
    executionId:String(input.executionId || 'preview'),publishStatus:'NOT_PUBLISHED',paidSpend:0};
}

function chooseReferences(ctx) {
  const seen = new Set();
  const unique = ctx.references.filter(r=>{const key=r.url.split(/[?#]/)[0];if(seen.has(key))return false;seen.add(key);return true;});
  const sorted = unique.sort((a,b)=>b.views-a.views);
  const qualified = sorted.filter(r=>r.views>10000000);
  return {...ctx,selectedReferences:(ctx.method.kind==='organic'&&!ctx.method.enhanced?qualified:sorted).slice(0,10),
    referenceNote:ctx.method.kind==='organic'?'Source recommends 10 relevant pages, videos over 10 million views and 10 original recordings/day. Imported view counts are user-supplied, not live-verified.':''};
}

