    if(method.kind==='roundup') lines=[hooks[i%hooks.length],...products.map((p,j)=>`${j+1}. ${p.name}. ${p.facts[0]?.text || '[ADD VERIFIED DETAIL]'}.`),ctx.cta];
    const scenes=times.map(([start,end],j)=>({start,end,visual:frames[Math.min(j,frames.length-1)],voiceover:lines[j],overlay:j===0?disclosure:lines[j],
      camera:['Medium eye-level, slight push-in','Stable product close-up','Slow side-to-side product view','Gentle return to medium framing','Locked product end card'][j],
      gesture:['Hold product visibly or indicate garment','Point once to the named detail','Demonstrate only the supplied authentic action','Open hand toward the product','Small invitation toward the CTA'][j],
      expression:['Curious, relaxed','Attentive','Matter-of-fact','Warm, subtle smile','Friendly, no exaggerated surprise'][j]}));
    const sourceSteps=method.sourceSteps.map((s,j)=>`${j+1}. ${s}`).join('\n');
    const providerSteps=ctx.provider==='Supercool' ? 'Open Supercool → Studio → Marketing Studio. Pick/reuse an adult influencer (or product-only POV), add authentic product photos/URL, select camera persona and opening psychology, paste this brief. Preview the credit quote; start with ONE variation. Review script and shot plan, Generate, then download the result. Return the MP4 to the n8n upload page.' : ctx.provider==='Higgsfield' ? 'Open your authenticated Higgsfield production surface. Select an available product/UGC or try-on workflow and verify its current model and credit quote. Use the supplied photos and timed brief; generate one test and download the MP4. Return it to n8n. No n8n MCP access or API endpoint is assumed.' : method.sourceHandoff;
