function reviewReceipt(pack,form,files) {
  const planOnly=form['Return type']==='Brief only';
  const errors=[];
  const ids=String(form['Returned variant IDs'] || '').split(',').map(x=>x.trim()).filter(Boolean);
  if(!planOnly) {
    if(String(form['Job ID']||'')!==String(pack.executionId)) errors.push('Job ID does not match this waiting execution.');
    if(!pack.production) errors.push('Start a Production run with complete product evidence before accepting rendered assets.');
    if(!files.length) errors.push('Upload at least one MP4/MOV file.');
    if(files.length!==ids.length) errors.push('Provide one variant ID for each uploaded file, in the same order.');
    if(new Set(ids).size!==ids.length || ids.some(id=>!pack.variants.some(v=>v.id===id))) errors.push('Returned variant IDs must be unique IDs shown in the brief.');
    if(form['Review result']!=='Checked product, text, sound and disclosures') errors.push('Complete the product, captions, audio and disclosure review.');
    for(const f of files) {
      if(!/\.(mp4|mov)$/i.test(f.name) || !f.validContainer) errors.push('Invalid video container: '+f.name);
      if(f.bytes>pack.maxUploadMB*1024*1024) errors.push('Video exceeds upload limit: '+f.name);
      if(!f.width||!f.height||f.width>=f.height) errors.push('Video must contain a vertical video track: '+f.name);
      const target=pack.variants.find(v=>v.id===ids[files.indexOf(f)])?.duration||30;
      if(!Number.isFinite(f.duration)||Math.abs(f.duration-target)>Math.max(3,target*0.2)) errors.push('Video duration is outside the target tolerance: '+f.name);
    }
    if(new Set(files.map(f=>f.sha256)).size!==files.length) errors.push('Duplicate renders detected by SHA-256.');
    const attempts=Number(form['Generation attempts']);
    if(!Number.isInteger(attempts)||attempts<1||attempts>pack.maxAttempts) errors.push('Generation attempts must be 1–'+pack.maxAttempts+'.');
    const finalText=String(form['Final transcript']||'');
    if(!finalText.trim()) errors.push('Paste the final transcript for copy checks.');
    for(const term of pack.prohibitedClaims) if(finalText.toLowerCase().includes(term.toLowerCase())) errors.push('Review prohibited wording in transcript: '+term);
    if(!Number.isFinite(Number(form['Credits used'])) || Number(form['Credits used'])<0) errors.push('Credits used must be a nonnegative number.');
  }
  return {valid:errors.length===0,errors,planOnly,ids,status:planOnly?'BRIEF_ONLY':'ASSETS_RETURNED_NOT_PUBLISHED',
    review:planOnly?'Not performed':form['Review result'],providerUsed:form['Provider used'] || pack.provider,creditsUsed:planOnly?0:Number(form['Credits used']),
    attempts:Number(form['Generation attempts']||0),actualTranscript:String(form['Final transcript'] || ''),renderedFiles:files.map((f,i)=>({...f,variantId:ids[i] || null})),
    automaticChecks:'MP4/MOV container structure, video-track dimensions, duration tolerance, size, SHA-256 duplicate detection, job and variant mapping, and configured prohibited phrases. Decoding, product/character identity, all factual claims, caption timing and audio quality require the recorded operator review.'};
}

